const docs = $json.documents || [];

const normalizeStudentSelection = (value) => {
  const normalized = String(value ?? '').trim().toLocaleUpperCase('tr-TR');
  return /^[A-E]$/.test(normalized) ? normalized : 'Bilinmiyor';
};

return docs.map(doc => ({
  json: {
    docName: doc.name,
    docId: doc.name.split('/').pop(),
    fotoLink: doc.fields?.fotoLink?.stringValue || null,
    durum: doc.fields?.durum?.stringValue || null,
    kullaniciEposta: doc.fields?.kullaniciEposta?.stringValue || null,
    tarih: doc.fields?.tarih?.stringValue || null,
    ogrenciSecimi: normalizeStudentSelection(doc.fields?.ogrenciSecimi?.stringValue)
  }
}));

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Birinci çözüm JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.answer || !parsed.topic) throw new Error('Birinci çözüm eksik alan içeriyor');
const confidence = Number(parsed.confidence);
const image = $("Görseli Base64'e Çevir").first().json;
return [{ json: { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), confidence: Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0, mimeType: image.mimeType, base64: image.base64, rawOpenAi: raw } }];

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;')
  .replace(/'/g, '&#39;');

const rawQuestion = $json.question || '';
const rawSteps = Array.isArray($json.steps) ? $json.steps : [];
const rawAnswer = $json.answer || '';
const rawTopic = $json.topic || '';
const verification = $json.verification || {};

const question = escapeHtml(rawQuestion);
const steps = rawSteps.map(escapeHtml);
const answer = escapeHtml(rawAnswer);
const topic = escapeHtml(rawTopic);
const stepsHtml = steps.map((step, index) => '<li><strong>Adım ' + (index + 1) + ':</strong> ' + step + '</li>').join('');

const html = '<!DOCTYPE html><html lang="tr"><head><meta charset="UTF-8"><style>' +
  'body{margin:0;padding:32px;background:#f3f4f6;font-family:Arial,sans-serif}' +
  '.card{width:900px;background:#fff;border-radius:24px;padding:36px;box-shadow:0 12px 40px rgba(0,0,0,.12);color:#111827}' +
  '.title{font-size:32px;font-weight:800;margin-bottom:16px}.topic{font-size:18px;color:#2563eb;margin-bottom:24px;font-weight:700}' +
  '.question{font-size:22px;line-height:1.5;margin-bottom:28px}ol{padding-left:24px;font-size:19px;line-height:1.6}li{margin-bottom:12px}' +
  '.verified{margin:0 0 20px;color:#166534;font-size:15px;font-weight:700}.answer{margin-top:32px;padding:20px;border-radius:16px;background:#dcfce7;font-size:26px;font-weight:800;color:#166534}' +
  '</style></head><body><div class="card"><div class="title">Soru Çözümü</div><div class="topic">' + topic +
  '</div><div class="verified">✓ Bağımsız AI doğrulamasından geçti</div><div class="question">' + question + '</div><ol>' + stepsHtml + '</ol><div class="answer">Cevap: ' + answer +
  '</div></div></body></html>';

return [{ json: { question: rawQuestion, steps: rawSteps, answer: rawAnswer, topic: rawTopic, lesson: String($json.lesson || "Diğer"), similarQuestions: Array.isArray($json.similarQuestions) ? $json.similarQuestions : [], verification, html } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{'); const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('İkinci çözüm JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.answer || !parsed.topic) throw new Error('İkinci çözüm eksik alan içeriyor');

const normalizeStudentSelection = (value) => {
  const normalized = String(value ?? '').trim().toLocaleUpperCase('tr-TR');
  return /^[A-E]$/.test(normalized) ? normalized : 'Bilinmiyor';
};
let pending = {};
let manual = {};
try { pending = $('Bekleyen Soruyu Kilitle ve Getir').first().json || {}; } catch (_) {}
try { manual = $('Soru Kayıtlarını Dönüştür').first().json || {}; } catch (_) {}
const studentSelection = normalizeStudentSelection(pending.ogrenciSecimi ?? manual.ogrenciSecimi);

const confidence = Number(parsed.confidence);
const primary = $('AI Yanıtını Ayrıştır').first().json;
const image = $("Görseli Base64'e Çevir").first().json;
const independent = { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), confidence: Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0 };
const primarySummary = { question: primary.question, steps: primary.steps, answer: primary.answer, topic: primary.topic, confidence: primary.confidence };
const judgePrompt = [
  'Görseldeki soruyu kendin yeniden çöz ve aşağıdaki iki kör aday çözümü kanıtlarıyla karşılaştır. Çoğunluğa körü körüne uyma.',
  'İlk iki çözücü öğrenci seçimini GÖRMEDEN çalıştı. Öğrenci seçimi yalnızca sonradan kullanılacak, güvenilmez bir karşılaştırma sinyalidir; doğru cevap kabul edilmemelidir.',
  'Öğrenci seçimi: ' + studentSelection,
  'Öğrenci seçimi A-E ise kendi doğruladığın final cevabın şık harfiyle karşılaştır. Uyuşmazlık öğrencinin yanlış seçmiş olabileceği anlamına gelir; yalnız bu seçime dayanarak cevabını değiştirme.',
  'Grafiklerde önce her doğrunun en az iki (x,y) noktasını ve eğimini çıkar. Bir noktanın x değerini yalnız o noktadan x eksenine inen kendi dikey kesikli kılavuzundan oku; yatay kılavuz x bilgisi taşımaz.',
  'Eşitliği yalnız aynı x koordinatında, yani aynı mutlak zamanda denetle. Sonradan başlayan nesnenin başlangıcından geçen süreyi ortak zamandan ayır ve sonucu denklemlere geri koy.',
  'Görsel net değilse, adaylar uyuşmuyorsa veya sonucu matematiksel/mantıksal olarak doğrulayamıyorsan approved=false ve needsManualReview=true yap. Güven 0.92 altında ise onaylama.',
  'lesson yalnızca şu 12 değerden biri olmalı ve yazımı birebir aynı olmalı: Matematik, Fizik, Kimya, Biyoloji, Türkçe, Edebiyat, Tarih, Coğrafya, Felsefe, Din Kültürü, İngilizce, Diğer.',
  'Ders eşleştirme: Geometri → Matematik; Türk Dili ve Edebiyatı → Edebiyat; Mantık, Psikoloji ve Sosyoloji → Felsefe; Din Kültürü ve Ahlak Bilgisi → Din Kültürü; yabancı dil ve YDT İngilizce → İngilizce.',
  'Paragraf, dil bilgisi, sözcükte ve cümlede anlam soruları Türkçe; edebiyat tarihi, edebi akımlar, nazım/şiir bilgisi ve yazar-eser soruları Edebiyat olarak işaretlenmeli.',
  'Diğer YALNIZCA bu derslerin hiçbirine uymayan sorularda kullanılmalı.',
  'Birinci kör çözüm: ' + JSON.stringify(primarySummary),
  'İkinci kör çözüm: ' + JSON.stringify(independent)
].join('\n');
return [{ json: { ...independent, independent, primary: primarySummary, studentSelection, judgePrompt, judgePromptJsonEscaped: JSON.stringify(judgePrompt).slice(1, -1), mimeType: image.mimeType, base64: image.base64, rawIndependent: raw } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{'); const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Hakem geçerli JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.steps.length || !parsed.answer || !parsed.topic || !parsed.lesson) throw new Error('Hakem sonucu eksik');

const optionLetter = (value) => {
  const text = String(value ?? '').trim().toLocaleUpperCase('tr-TR');
  const match = text.match(/^(?:CEVAP\s*[:=-]?\s*)?([A-E])(?:[).:\s-]|$)/);
  return match ? match[1] : null;
};
const judgeInput = $('İkinci Çözümü Ayrıştır').first().json;
const studentSelection = /^[A-E]$/.test(String(judgeInput.studentSelection || '')) ? String(judgeInput.studentSelection) : 'Bilinmiyor';
const finalAnswerLetter = optionLetter(parsed.answer);
const selectionKnown = studentSelection !== 'Bilinmiyor';
const studentSelectionMatchesFinal = selectionKnown && finalAnswerLetter !== null ? studentSelection === finalAnswerLetter : null;
const requiresBlindRetry = selectionKnown && studentSelectionMatchesFinal !== true;
const confidence = Number(parsed.confidence);
const safeConfidence = Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0;
const judgeApproved = parsed.approved === true && parsed.needsManualReview !== true && safeConfidence >= 0.92;
const approved = judgeApproved && !requiresBlindRetry;
const verification = {
  approved, judgeApproved, confidence: safeConfidence,
  primaryAnswer: String(parsed.primaryAnswer ?? ''),
  independentAnswer: String(parsed.independentAnswer ?? ''),
  finalAnswer: String(parsed.answer), finalAnswerLetter,
  studentSelection, studentSelectionMatchesFinal, requiresBlindRetry,
  rationale: String(parsed.rationale ?? '')
};
return [{ json: { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), lesson: String(parsed.lesson), verificationApproved: approved, verification } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{'); const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Güçlü model geçerli JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
if (!parsed.question || !Array.isArray(parsed.steps) || !parsed.steps.length || !parsed.answer || !parsed.topic || !parsed.lesson) throw new Error('Güçlü çözüm eksik');
const optionLetter = (value) => {
  const text = String(value ?? '').trim().toLocaleUpperCase('tr-TR');
  const match = text.match(/^(?:CEVAP\s*[:=-]?\s*)?([A-E])(?:[).:\s-]|$)/);
  return match ? match[1] : null;
};
const confidence = Number(parsed.confidence);
const safeConfidence = Number.isFinite(confidence) ? Math.max(0, Math.min(1, confidence)) : 0;
const approved = parsed.approved === true && parsed.needsManualReview !== true && safeConfidence >= 0.94;
const previous = $('Güçlü Yeniden Çözüm İstemini Hazırla').first().json.previousVerification || {};
const finalAnswerLetter = optionLetter(parsed.answer);
const studentSelection = /^[A-E]$/.test(String(previous.studentSelection || '')) ? String(previous.studentSelection) : 'Bilinmiyor';
const studentSelectionMatchesFinal = studentSelection !== 'Bilinmiyor' && finalAnswerLetter !== null ? studentSelection === finalAnswerLetter : null;
const verification = {
  approved, confidence: safeConfidence,
  finalAnswer: String(parsed.answer), finalAnswerLetter,
  studentSelection, studentSelectionMatchesFinal,
  rationale: String(parsed.rationale || ''),
  escalatedToStrongModel: true,
  strongModelWasBlindToStudentSelection: true,
  previousJudge: previous
};
return [{ json: { question: String(parsed.question), steps: parsed.steps.map(String), answer: String(parsed.answer), topic: String(parsed.topic), lesson: String(parsed.lesson), verificationApproved: approved, verification } }];

const solution = $json;
const source = {
  question: String(solution.question || ''),
  steps: Array.isArray(solution.steps) ? solution.steps.map(String) : [],
  answer: String(solution.answer || ''),
  topic: String(solution.topic || ''),
  lesson: String(solution.lesson || 'Diğer')
};
const prompt = [
  'Aşağıdaki doğrulanmış soru ve çözümle aynı konu ve kazanımı ölçen üç özgün çoktan seçmeli soru üret.',
  'Sıra ve seviye tam olarak kolay, orta, zor olsun.',
  'Her soruda tam 5 seçenek bulunmalı ve A), B), C), D), E) ön ekleriyle sıralanmalıdır.',
  'correct_option, options dizisindeki doğru seçeneğin tamamıyla birebir aynı olmalıdır.',
  'Çözüm adımları kısa, doğru ve kontrol edilmiş olsun. Kaynak soruyu kopyalama.',
  'Doğrulanmış kaynak: ' + JSON.stringify(source)
].join('\n');
return [{ json: { ...solution, similarPrompt: prompt, similarPromptJsonEscaped: JSON.stringify(prompt).slice(1, -1) } }];

const raw = $json.choices?.[0]?.message?.content ?? '';
const fence = String.fromCharCode(96).repeat(3);
const cleaned = String(raw).replaceAll(fence + 'json', '').replaceAll(fence, '').trim();
const start = cleaned.indexOf('{'); const end = cleaned.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('Benzer soru modeli geçerli JSON döndürmedi');
const parsed = JSON.parse(cleaned.slice(start, end + 1));
const expectedLevels = ['kolay', 'orta', 'zor'];
if (!Array.isArray(parsed.similarQuestions) || parsed.similarQuestions.length !== 3) throw new Error('Üç benzer soru üretilmedi');
const similarQuestions = parsed.similarQuestions.map((item, index) => {
  const level = String(item?.level ?? '').toLocaleLowerCase('tr-TR');
  const options = Array.isArray(item?.options) ? item.options.map(String).map(value => value.trim()).filter(Boolean) : [];
  const correctOption = String(item?.correct_option ?? '').trim();
  const labels = ['A', 'B', 'C', 'D', 'E'];
  if (level !== expectedLevels[index] || !item?.question || !Array.isArray(item?.steps) || !item.steps.length || !item?.answer) throw new Error(expectedLevels[index] + ' benzer soru geçersiz');
  if (options.length !== 5) throw new Error(level + ' sorusunda 5 şık bulunmuyor');
  if (!options.every((option, i) => new RegExp('^' + labels[i] + '[).:-]\\s*', 'i').test(option))) throw new Error(level + ' sorusunun şıkları A-E biçiminde değil');
  const answerText = String(item?.answer ?? '').trim();
  const correctLabel = (correctOption.match(/^([A-E])(?:[).:\-]|\s|$)/i)?.[1]
    || answerText.match(/^([A-E])(?:[).:\-]|\s|$)/i)?.[1])?.toUpperCase();
  const stripLabel = value => String(value || '').replace(/^[A-E][).:-]\s*/i, '').trim().toLocaleLowerCase('tr-TR');
  const correctText = stripLabel(correctOption);
  const normalizedCorrectOption = options.includes(correctOption)
    ? correctOption
    : options.find(option => correctLabel && new RegExp('^' + correctLabel + '[).:-]\\s*', 'i').test(option))
      || options.find(option => correctText && stripLabel(option) === correctText)
      || correctOption;
  if (!normalizedCorrectOption) throw new Error(level + ' sorusunda doğru şık boş');
  return { level, question: String(item.question), steps: item.steps.map(String), answer: String(item.answer), options, correct_option: normalizedCorrectOption };
});
const solution = $('Benzer Soru İstemini Hazırla').first().json;
return [{ json: { question: solution.question, steps: solution.steps, answer: solution.answer, topic: solution.topic, lesson: solution.lesson, verificationApproved: solution.verificationApproved, verification: solution.verification, similarQuestions } }];
